<script lang="ts">
    import { timerState, timerSound, customPresets, timerPresets, selectTimer, startTimer, pauseTimer, resetTimer, setTimerSound, addTimerPreset, removeTimerPreset, formatTimer } from "@/lib/timer"
    let settings = false, adding = false, label = "", hours = 0, minutes = 5, seconds = 0, formError = ""
    let customTime=false
    function applyCustomTime(){
        formError=''
        if($timerState.phase==='running')return
        if(![hours,minutes,seconds].every(value=>Number.isInteger(value)&&value>=0)||hours>23||minutes>59||seconds>59||hours*3600+minutes*60+seconds<1){formError='Укажите время от 1 секунды до 23:59:59.';return}
        selectTimer({id:'custom-time',label:'Своё время',seconds:hours*3600+minutes*60+seconds,icon:'◷'})
        customTime=false
    }
    $: ratio = $timerState.remaining / $timerState.total
    $: circumference = 2 * Math.PI * 112
    $: phaseLabel = ({ idle: "Готов к запуску", running: "Время идёт", paused: "На паузе", finished: "Время вышло" })[$timerState.phase]
    function addPreset() {
        formError = ""
        if (![hours, minutes, seconds].every(value => Number.isInteger(value) && value >= 0) || hours > 23 || minutes > 59 || seconds > 59) { formError = "Укажите корректное время: до 23 часов, 59 минут и 59 секунд."; return }
        if (!addTimerPreset(label, hours * 3600 + minutes * 60 + seconds)) { formError = "Введите название и время больше нуля. Можно сохранить до 20 своих пресетов."; return }
        adding = false; label = ""
    }
</script>

<section class="timer-card" aria-label="Таймер">
    <header><div><p class="kicker">ЦЕНТР · ВАШЕ ВРЕМЯ</p><h2>Таймер</h2></div><button class="settings-button" on:click={() => settings = !settings} aria-label="Настройки таймера" aria-expanded={settings}>⚙</button></header>
    {#if settings}<div class="timer-settings"><label><input type="checkbox" checked={$timerSound} on:change={event => setTimerSound(event.currentTarget.checked)}/> Звуковой сигнал при завершении</label><small>Отсчёт сохраняется при переключении вкладок и перезапуске JARVIS.</small></div>{/if}
    <button class="add-preset custom-time" disabled={$timerState.phase==='running'} aria-expanded={customTime} on:click={()=>{customTime=!customTime;adding=false;formError=''}}>◷ Своё время</button>
    {#if customTime}<form class="preset-form" on:submit|preventDefault={applyCustomTime}><h3>Задайте свой отсчёт</h3><div class="time-fields"><label>Часы<input type="number" min="0" max="23" step="1" bind:value={hours} required/></label><label>Минуты<input type="number" min="0" max="59" step="1" bind:value={minutes} required/></label><label>Секунды<input type="number" min="0" max="59" step="1" bind:value={seconds} required/></label></div>{#if formError}<p class="form-error" role="alert">{formError}</p>{/if}<button class="save-preset" disabled={$timerState.phase==='running'}>Установить время</button><small>Без сохранения пресета. После установки нажмите «Старт».</small></form>{/if}
    <div class="timer-layout">
        <aside class="preset-panel" aria-label="Пресеты таймера"><h3><span>◷</span> Пресеты</h3><div class="presets">{#each [...timerPresets, ...$customPresets] as preset, index (preset.id)}<div class="preset-row" class:split={index === 6}><button class="preset" class:selected={$timerState.label === preset.label && $timerState.total === preset.seconds} disabled={$timerState.phase === "running"} on:click={() => selectTimer(preset)} aria-pressed={$timerState.label === preset.label && $timerState.total === preset.seconds}><span class="preset-icon" aria-hidden="true">{preset.icon}</span><span class="preset-label">{preset.label}</span><time>{formatTimer(preset.seconds, true)}</time></button>{#if index >= timerPresets.length}<button class="remove" disabled={$timerState.phase === "running"} on:click={() => removeTimerPreset(preset.id)} aria-label={`Удалить пресет ${preset.label}`}>×</button>{/if}</div>{/each}</div><button class="add-preset" disabled={$timerState.phase === "running"} on:click={() => adding = !adding} aria-expanded={adding}>＋ Добавить пресет</button></aside>
        <div class="timer-main"><div class="dial" class:running={$timerState.phase === "running"} class:finished={$timerState.phase === "finished"}><svg viewBox="0 0 260 260" aria-hidden="true"><defs><linearGradient id="timer-ring" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#6df4e5"/><stop offset="1" stop-color="#0cabad"/></linearGradient></defs><circle class="ring-track" cx="130" cy="130" r="112"/><circle class="ring-progress" cx="130" cy="130" r="112" stroke-dasharray={circumference} stroke-dashoffset={circumference * (1 - ratio)} transform="rotate(-90 130 130)"/><circle cx={130 + 112 * Math.cos(2 * Math.PI * ratio - Math.PI / 2)} cy={130 + 112 * Math.sin(2 * Math.PI * ratio - Math.PI / 2)} r="5.5" fill="#e0fff8" stroke="#fff" stroke-width="1"/></svg><div class="dial-copy"><p>{$timerState.label}</p><time class:hours={$timerState.remaining >= 3600}>{formatTimer($timerState.remaining)}</time><div class="time-labels">{$timerState.remaining >= 3600 ? "ЧАС · МИН · СЕК" : "МИН · СЕК"}</div><span class="phase">{phaseLabel}</span></div></div><div class="timer-controls"><button class="round-control" on:click={resetTimer} aria-label="Сбросить таймер"><span>↺</span><small>Сброс</small></button><button class="start-control" disabled={$timerState.phase === "running"} on:click={startTimer}><span aria-hidden="true">▶</span>{$timerState.phase === "paused" ? "Продолжить" : $timerState.phase === "finished" ? "Ещё раз" : "Старт"}</button><button class="round-control" disabled={$timerState.phase !== "running"} on:click={pauseTimer} aria-label="Поставить таймер на паузу"><span>Ⅱ</span><small>Пауза</small></button></div><p class="background-hint">Можно перейти в другой раздел — таймер продолжит работать.</p></div>
    </div>
    {#if adding}<form class="preset-form" on:submit|preventDefault={addPreset}><h3>Свой интервал</h3><input aria-label="Название пресета" placeholder="Например: отдых для глаз" bind:value={label} maxlength="40" required/><div class="time-fields"><label>Часы<input type="number" min="0" max="23" step="1" bind:value={hours} required/></label><label>Минуты<input type="number" min="0" max="59" step="1" bind:value={minutes} required/></label><label>Секунды<input type="number" min="0" max="59" step="1" bind:value={seconds} required/></label></div>{#if formError}<p class="form-error" role="alert">{formError}</p>{/if}<button class="save-preset" disabled={$timerState.phase === "running"}>Сохранить пресет</button></form>{/if}
</section>

<style lang="scss">
    .custom-time{width:auto;margin:0 0 1rem;padding:.65rem 1rem}.preset-form small{color:var(--timer-muted);font-size:.65rem}.preset-form{margin-bottom:1rem}
    .timer-card{--timer-cyan:#19d4cd;--timer-muted:#8daeb0;--timer-border:#29484c;padding:1rem;border:1px solid #305358;border-radius:16px;background:radial-gradient(ellipse at 90% 85%,#07595455,transparent 65%),linear-gradient(140deg,#0d2023,#060f12);color:#eefbfa;font-family:"Manrope Variable",sans-serif;box-shadow:0 16px 36px #0003;container-type:inline-size}.timer-card header{display:flex;align-items:center;justify-content:space-between;margin-bottom:1.1rem}.kicker{margin:0;color:#52fefe;font-size:.58rem;letter-spacing:.14em;font-weight:800}.timer-card h2{margin:.35rem 0 0;font-size:1.5rem;letter-spacing:-.035em}.settings-button{display:grid;place-items:center;width:31px;height:31px;border:1px solid #32575a;border-radius:9px;background:#152c30;color:#c8eeeb;font-size:21px;cursor:pointer}.timer-layout{display:grid;grid-template-columns:minmax(120px,.85fr) minmax(0,1.65fr);gap:1rem;align-items:start}.preset-panel h3{display:flex;gap:.45rem;align-items:center;margin:0 0 .6rem;font-size:.78rem;font-weight:600}.preset-panel h3 span{color:#b5dddb;font-size:1.2rem}.presets{display:grid;gap:.3rem}.preset-row{display:flex;min-width:0;position:relative}.preset-row.split{border-top:1px solid #2c4c50;margin-top:.35rem;padding-top:.6rem}.preset{display:flex;align-items:center;gap:.4rem;width:100%;padding:.45rem .4rem;border:1px solid #26494d;border-radius:8px;background:#10272b;color:#d0e9e7;text-align:left;cursor:pointer;min-width:0;transition:border-color .18s,background .18s}.preset:hover:not(:disabled){background:#183d40;border-color:#54b7b2}.preset.selected{border-color:#52fefe;background:linear-gradient(110deg,#18bdb6,#087d83);color:#fff;box-shadow:0 3px 14px #00ded522}.preset-icon{display:grid;place-items:center;flex:none;width:23px;height:23px;border-radius:6px;background:#ffffff0b;color:#a8ddda;font-size:16px}.selected .preset-icon{color:#fff;background:#ffffff18}.preset-label{flex:1;min-width:0;font-size:.62rem;overflow-wrap:anywhere}.preset time{color:#8cafb0;font-size:.5rem;font-variant-numeric:tabular-nums}.selected time{color:#e0fffa}.preset:disabled:not(.selected){opacity:.6;cursor:not-allowed}.remove{flex:none;width:20px;border:0;background:transparent;color:#bd8791;cursor:pointer}.add-preset{margin-top:.65rem;padding:.6rem .4rem;width:100%;border:1px solid #31565a;border-radius:8px;background:#152e32;color:#b4dedb;font:600 .61rem "Manrope Variable",sans-serif;cursor:pointer}.timer-main{min-width:0;padding-top:.8rem}.dial{position:relative;width:100%;max-width:350px;margin:auto;aspect-ratio:1;filter:drop-shadow(0 6px 20px #006f682b)}.dial svg{display:block;width:100%;height:100%;overflow:visible}.ring-track,.ring-progress{fill:none;stroke-width:12}.ring-track{stroke:#294a4e}.ring-progress{stroke:url(#timer-ring);stroke-linecap:round;transition:stroke-dashoffset .25s linear}.finished .ring-track{stroke:#1d616e}.dial-copy{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;pointer-events:none}.dial-copy p{max-width:65%;margin:0 0 .65rem;color:#8fbab9;font-size:.66rem;text-align:center;overflow-wrap:anywhere}.dial-copy time{color:#f0fffc;font-size:clamp(2rem,13cqw,4rem);font-weight:700;line-height:1.1;letter-spacing:-.055em;font-variant-numeric:tabular-nums;text-shadow:0 4px 24px #65ffec20}.dial-copy time.hours{font-size:clamp(1.5rem,9cqw,2.8rem)}.time-labels{margin-top:.6rem;font-size:.56rem;letter-spacing:.2em;color:#7fa5a6}.phase{margin-top:.8rem;padding:.2rem .5rem;border:1px solid #23484b;border-radius:12px;color:#86b1b1;font-size:.55rem}.running .phase{color:#a6fff2;border-color:#287c79}.finished .phase{color:#97f5df;border-color:#306e6c}.timer-controls{display:flex;align-items:flex-start;justify-content:center;gap:.5rem;margin-top:1rem}.round-control{display:flex;align-items:center;flex-direction:column;gap:.25rem;padding:0;border:0;background:transparent;color:#b2d9d7;cursor:pointer}.round-control>span{display:grid;place-items:center;width:36px;height:36px;border:1px solid #34585c;border-radius:50%;background:#112d31;font-size:22px}.round-control small{font-size:.55rem}.round-control:disabled{opacity:.35;cursor:default}.start-control{display:flex;align-items:center;justify-content:center;gap:.4rem;flex:1;max-width:160px;min-height:38px;padding:.5rem .6rem;border:1px solid #54f4e8;border-radius:24px;background:linear-gradient(#28ddd4,#0aa5ac);color:white;font:700 .75rem "Manrope Variable",sans-serif;box-shadow:0 6px 22px #00dacc2b;cursor:pointer}.start-control:disabled{opacity:.55;cursor:default}.start-control span{font-size:14px}.background-hint{margin:1rem 0 0;color:#719c9d;font-size:.6rem;line-height:1.6;text-align:center}.timer-settings{display:flex;flex-direction:column;gap:.6rem;margin:0 0 1rem;padding:.75rem;border:1px solid #2c5558;border-radius:9px;background:#102d31}.timer-settings label{font-size:.7rem;display:flex;align-items:center;gap:.45rem}.timer-settings input{accent-color:#1aeadb}.timer-settings small{font-size:.6rem;color:#84abaa;line-height:1.5}.preset-form{display:grid;gap:.55rem;margin-top:1rem;padding:.85rem;border:1px solid #31565a;border-radius:10px;background:#102b2f}.preset-form h3{margin:0;font-size:.85rem}.preset-form input{min-width:0;width:100%;padding:.5rem;border:1px solid #355c60;border-radius:6px;background:#081d20;color:#e6fffa;font:600 .7rem "Manrope Variable",sans-serif;outline:none}.preset-form input:focus{border-color:#59f2df}.time-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.5rem}.time-fields label{display:grid;gap:.2rem;color:#8cb5b3;font-size:.6rem}.save-preset{padding:.6rem;border:1px solid #5aeadc;border-radius:7px;background:#107d7b;color:white;font:700 .7rem "Manrope Variable",sans-serif;cursor:pointer}.form-error{margin:0;font-size:.65rem;color:#ffb3b3}button:focus-visible{outline:2px solid #93ffe9;outline-offset:3px}@container(max-width:360px){.timer-layout{grid-template-columns:1fr}.presets{grid-template-columns:repeat(2,minmax(0,1fr))}.preset-row.split{border:0;margin:0;padding:0}.timer-main{grid-row:1}.dial{max-width:260px}.dial-copy time{font-size:3rem}.dial-copy time.hours{font-size:2rem}}@media(prefers-reduced-motion:reduce){.ring-progress,.preset{transition:none}}
</style>
